import pandas as pd

df = pd.read_csv("housing.csv")

def _find_median_house_value_column(df):
    cols = list(df.columns)
    lower_cols = {col: col.lower() for col in cols}
    # 1. exact sensible match: contains median, house, and value
    for col in cols:
        lname = lower_cols[col]
        if 'median' in lname and 'house' in lname and 'value' in lname:
            return col
    # 2. median + value
    for col in cols:
        lname = lower_cols[col]
        if 'median' in lname and 'value' in lname:
            return col
    # 3. median + house
    for col in cols:
        lname = lower_cols[col]
        if 'median' in lname and 'house' in lname:
            return col
    # 4. any column with 'median' that is numeric
    for col in cols:
        if 'median' in lower_cols[col]:
            if pd.api.types.is_numeric_dtype(df[col]) or pd.to_numeric(df[col], errors='coerce').notna().any():
                return col
    # 5. any column with 'house' and 'value'
    for col in cols:
        lname = lower_cols[col]
        if 'house' in lname and 'value' in lname:
            return col
    # 6. any column with 'value' that is numeric
    for col in cols:
        if 'value' in lower_cols[col]:
            if pd.api.types.is_numeric_dtype(df[col]) or pd.to_numeric(df[col], errors='coerce').notna().any():
                return col
    # 7. common fallback name
    if 'median_house_value' in cols:
        return 'median_house_value'
    # 8. give up
    raise KeyError("Could not find a median house value column")

col = _find_median_house_value_column(df)
