import pandas as pd

df = pd.read_csv('housing.csv')

if 'ocean_proximity' not in df.columns or 'median_house_value' not in df.columns:
    result = None
else:
    grp = (
        df.dropna(subset=['ocean_proximity', 'median_house_value'])
          .groupby('ocean_proximity', dropna=True)['median_house_value']
          .mean()
    )
    if grp.empty:
        result = None
    else:
        max_val = grp.max()
        top_categories = grp[grp == max_val].index.tolist()
        result = top_categories[0] if len(top_categories) == 1 else top_categories

import pandas as pd

df = pd.read_csv("housing.csv")

# Helper: find best candidate column by keywords and numeric dtype
def find_price_column(df):
    keywords = ['price', 'list_price', 'sale_price', 'amount', 'cost', 'median_price', 'saleamount']
    candidates = [c for c in df.columns if any(k in c.lower() for k in keywords)]
    # prefer numeric candidates with most non-null values
    numeric_candidates = [c for c in candidates if pd.api.types.is_numeric_dtype(df[c])]
    if numeric_candidates:
        numeric_candidates.sort(key=lambda c: df[c].notna().sum(), reverse=True)
        return numeric_candidates[0]
    # fallback: any numeric column with 'price' substring not present
    numeric_cols = [c for c in df.columns if pd.api.types.is_numeric_dtype(df[c])]
    if not numeric_cols:
        return None
    # choose numeric col with highest mean (likely price-like) or highest non-null count
    numeric_cols.sort(key=lambda c: df[c].notna().sum(), reverse=True)
    return numeric_cols[0]

def find_geo_column(df):
    # common geographic column names in order of preference
    geo_keywords_priority = ['neighborhood', 'neigh', 'zipcode', 'zip_code', 'zip', 'postal', 'city', 'town', 'region', 'area', 'location', 'district']
    cols = list(df.columns)
    lower_map = {c: c.lower() for c in cols}
    for kw in geo_keywords_priority:
        for c, lc in lower_map.items():
            if kw == lc or kw in lc:
                # ensure it's not all unique (i.e., maybe id) and not numeric ID-like
                if df[c].nunique() >= 2 and df[c].nunique() <= len(df) * 0.99:
                    return c
    # fallback: choose object dtype with reasonable cardinality
    obj_cols = [c for c in df.columns if df[c].dtype == object]
    for c in obj_cols:
        if 1 < df[c].nunique() <= len(df) * 0.99:
            return c
    # final fallback: choose any column with >1 unique values
    for c in df.columns:
        if 1 < df[c].nunique() <= len(df) * 0.99:
            return c
    return None

price_col = find_price_column(df)
geo_col = find_geo_column(df)

if price_col is None or geo_col is None:
    result = {
        "error": "Could not identify price column or geographic column automatically.",
        "detected_columns": {"columns": list(df.columns), "price_col": price_col, "geo_col": geo_col}
    }
else:
    # prepare list of numeric features to analyze as potential drivers
    possible_features = {
        "sqft": ['sqft', 'square_feet', 'living_area', 'area_sqft', 'size_sqft'],
        "bedrooms": ['bedrooms', 'beds', 'bd'],
        "bathrooms": ['bathrooms', 'baths', 'ba'],
        "year_built": ['year_built', 'built_year', 'yr_built'],
        "lot_size": ['lot_size', 'lotarea', 'lot_sqft', 'lot_sq_ft'],
        "hoa": ['hoa', 'hoa_fee', 'hoa_monthly'],
        "school_rating": ['school_rating', 'schools_score', 'school_score'],
        "median_income": ['median_income', 'income'],
        "distance_to_city": ['distance_to_city', 'dist_to_city', 'distance'],
    }
    # detect which of these exist
    detected_features = {}
    for feat, keys in possible_features.items():
        for c in df.columns:
            if any(k in c.lower() for k in keys) and pd.api.types.is_numeric_dtype(df[c]):
                detected_features[feat] = c
                break

    # detect boolean flags such as waterfront, pool, view
    flag_keywords = {
        "waterfront": ['waterfront', 'water_front', 'on_water'],
        "pool": ['pool', 'has_pool'],
        "view": ['view', 'has_view'],
        "garage": ['garage'],
    }
    detected_flags = {}
    for flag, keys in flag_keywords.items():
        for c in df.columns:
            if any(k in c.lower() for k in keys):
                # treat as flag if it is boolean or small-range numeric or object with yes/no
                s = df[c].dropna()
                if s.empty:
                    continue
                nunique = s.nunique()
                # accept object or numeric with few unique values
                if pd.api.types.is_bool_dtype(s) or (pd.api.types.is_numeric_dtype(s) and nunique <= 5) or (pd.api.types.is_object_dtype(s) and nunique <= 10):
                    detected_flags[flag] = c
                    break

    # Create aggregation dict
    agg_dict = {
        "mean_price": (price_col, "mean"),
        "median_price": (price_col, "median"),
        "count": (price_col, "count"),
        "std_price": (price_col, "std"),
    }
    # add detected numeric features averages
    for feat, colname in detected_features.items():
        agg_dict[f"avg_{feat}"] = (colname, "mean")
    # add flag averages (interpreted as prevalence)
    for flag, colname in detected_flags.items():
        # compute prevalence as mean after mapping truthy values to 1
        def _mean_flag(series):
            # convert common truthy strings to 1
            if pd.api.types.is_object_dtype(series):
                s = series.astype(str).str.lower().map(lambda x: 1 if x.strip() in ['yes','true','y','1','t'] else 0)
                return s.mean()
            if pd.api.types.is_bool_dtype(series):
                return series.mean()
            # numeric: treat >0 as true
            return (series > 0).mean()
        agg_dict[f"pct_{flag}"] = (colname, _mean_flag)

    # perform groupby aggregation
    grouped = df.groupby(geo_col).agg(**agg_dict)
    # ensure mean_price numeric
    grouped = grouped.sort_values("mean_price", ascending=False)
    top5 = grouped.head(5).reset_index()

    # compute dataset medians for comparisons
    comp_cols = [price_col] + list(detected_features.values())
    comp_df = df[comp_cols].copy()
    dataset_medians = comp_df.median(numeric_only=True)

    # build explanations for each top area
    explanations = {}
    for _, row in top5.iterrows():
        area = row[geo_col] if geo_col in row else row[geo_col]
        mean_price = row["mean_price"]
        median_price = row["median_price"]
        count = int(row["count"])
        parts = []
        parts.append(f"{area}: mean price {mean_price:.2f}, median price {median_price:.2f} (n={count})")
        # caution for small sample
        if count < max(3, len(df) * 0.01):
            parts.append("Caution: small sample size for this area; price estimate may be volatile.")
        # compare numeric features
        drivers = []
        for feat, colname in detected_features.items():
            area_feat = row.get(f"avg_{feat}", None)
            if pd.isna(area_feat):
                continue
            median_feat = dataset_medians.get(colname, None)
            if pd.isna(median_feat) or median_feat is None:
                continue
            # For some features, interpret direction (higher sqft, beds increase price; for year_built higher means newer -> higher; for distance lower increases price)
            if feat in ["sqft", "bedrooms", "bathrooms", "lot_size", "median_income", "school_rating"]:
                if area_feat > median_feat:
                    drivers.append(f"higher {feat.replace('_',' ')} ({area_feat:.1f} vs median {median_feat:.1f})")
            elif feat == "year_built":
                # newer houses have larger year_built
                if area_feat > median_feat:
                    drivers.append(f"newer homes (avg year_built {area_feat:.0f} vs median {median_feat:.0f})")
            elif feat == "distance_to_city":
                # smaller distance likely increases price
                if area_feat < median_feat:
                    drivers.append(f"closer to city ({area_feat:.1f} vs median {median_feat:.1f})")
            else:
                # generic
                if area_feat > median_feat:
                    drivers.append(f"higher {feat} ({area_feat:.1f} vs median {median_feat:.1f})")
        # flags
        for flag, colname in detected_flags.items():
            pct_flag = row.get(f"pct_{flag}", None)
            if pd.isna(pct_flag):
                continue
            dataset_pct = None
            # compute dataset prevalence
            ser = df[colname].dropna()
            if not ser.empty:
                if pd.api.types.is_object_dtype(ser):
                    s = ser.astype(str).str.lower().map(lambda x: 1 if x.strip() in ['yes','true','y','1','t'] else 0)
                    dataset_pct = s.mean()
                elif pd.api.types.is_bool_dtype(ser):
                    dataset_pct = ser.mean()
                else:
                    dataset_pct = (ser > 0).mean()
            if dataset_pct is not None and pct_flag > dataset_pct:
                drivers.append(f"higher prevalence of {flag} ({pct_flag:.2%} vs {dataset_pct:.2%} dataset)")
        if drivers:
            parts.append("Key contributing factors: " + "; ".join(drivers) + ".")
        else:
            parts.append("No clear data-driven differentiators found in available features; prices may be driven by intangible factors (location desirability, lifestyle, micro-market).")
        explanations[str(area)] = " ".join(parts)

    # prepare a tidy top5 DataFrame for result (format numeric columns)
    top5_clean = top5.copy()
    # round numeric columns for readability
    for c in top5_clean.columns:
        if pd.api.types.is_float_dtype(top5_clean[c]) and c != geo_col:
            top5_clean[c] = top5_clean[c].round(3)

    result = {
        "price_column_detected": price_col,
        "geo_column_detected": geo_col,
        "top_5_areas": top5_clean,
        "explanations": explanations,
        "detected_numeric_features": detected_features,
        "detected_flag_features": detected_flags
    }

import pandas as pd

df = pd.read_csv("housing.csv")

# Helper to find a column by checking candidate names or by scanning content
def find_column_by_names(candidates):
    cols_lower = {c.lower(): c for c in df.columns}
    for cand in candidates:
        if cand.lower() in cols_lower:
            return cols_lower[cand.lower()]
    return None

# Common candidates
price_col = find_column_by_names([
    "median_house_value", "median_household_value", "house_value", "median_price", "price", "median_housevalue"
])
income_col = find_column_by_names([
    "median_income", "median_household_income", "income", "household_income"
])
ocean_col = find_column_by_names([
    "ocean_proximity", "ocean proximity", "proximity_to_ocean", "near_ocean"
])

# If ocean_col not found by name, try detecting a categorical column that contains 'ocean' or 'bay' in values
if ocean_col is None:
    for c in df.columns:
        if df[c].dtype == object:
            sample_vals = df[c].dropna().astype(str).str.lower().unique()[:50]
            if any(("ocean" in v or "bay" in v) for v in sample_vals):
                ocean_col = c
                break

# If price_col not found by name, try finding a numeric column that looks like a value/price
if price_col is None:
    for c in df.select_dtypes(include=["number"]).columns:
        if "value" in c.lower() or "price" in c.lower() or "median" in c.lower():
            price_col = c
            break
# If still None, try the first numeric column
if price_col is None:
    numeric_cols = df.select_dtypes(include=["number"]).columns.tolist()
    price_col = numeric_cols[0] if numeric_cols else None

# If income_col not found, try to find a plausible numeric income-like column name
if income_col is None:
    for c in df.select_dtypes(include=["number"]).columns:
        if "income" in c.lower() or "median" in c.lower() and "income" in c.lower():
            income_col = c
            break

# If no ocean column found at all, create an empty result indicating inability to identify coastal areas
if ocean_col is None or price_col is None:
    result = {
        "error": "Could not reliably identify ocean proximity column or price column in the CSV.",
        "detected_columns": list(df.columns)
    }
else:
    # Identify coastal rows by checking if the ocean column contains 'ocean' or 'bay' (case-insensitive)
    coastal_mask = df[ocean_col].astype(str).str.lower().str.contains("ocean") | df[ocean_col].astype(str).str.lower().str.contains("bay")
    coastal_df = df[coastal_mask].copy()
    coastal_df = coastal_df.reset_index(drop=True)

    # Ensure price column is numeric
    coastal_df[price_col] = pd.to_numeric(coastal_df[price_col], errors="coerce")

    # Basic summary of coastal prices
    coastal_price_series = coastal_df[price_col].dropna()
    coastal_count = len(coastal_price_series)
    coastal_mean = coastal_price_series.mean() if coastal_count > 0 else None
    coastal_q25 = coastal_price_series.quantile(0.25) if coastal_count > 0 else None
    coastal_std = coastal_price_series.std() if coastal_count > 0 else None

    # Try to explain low coastal prices using median income if available
    explanatory_features = []
    if income_col is not None and income_col in coastal_df.columns:
        coastal_df[income_col] = pd.to_numeric(coastal_df[income_col], errors="coerce")
        reg_df = coastal_df[[income_col, price_col]].dropna()
        if len(reg_df) >= 3 and reg_df[income_col].var() != 0:
            x = reg_df[income_col]
            y = reg_df[price_col]
            slope = x.cov(y) / x.var()
            intercept = y.mean() - slope * x.mean()
            # Compute predicted and residuals for all coastal rows (NaN if income missing)
            coastal_df["_predicted_price_by_income"] = coastal_df[income_col].apply(lambda v: intercept + slope * v if pd.notnull(v) else pd.NA)
            coastal_df["_price_residual"] = coastal_df[price_col] - coastal_df["_predicted_price_by_income"]
            explanatory_features.append(income_col)
        else:
            coastal_df["_predicted_price_by_income"] = pd.NA
            coastal_df["_price_residual"] = pd.NA
    else:
        coastal_df["_predicted_price_by_income"] = pd.NA
        coastal_df["_price_residual"] = pd.NA

    # Compute a few additional potentially explanatory metrics if relevant columns exist
    def safe_div(a, b):
        if pd.isna(a) or pd.isna(b) or b == 0:
            return pd.NA
        return a / b

    # Common columns from California housing dataset
    for col in ["total_rooms", "total_bedrooms", "population", "households", "housing_median_age"]:
        if col in coastal_df.columns:
            explanatory_features.append(col)
    # Add computed ratios
    if "total_rooms" in coastal_df.columns and "households" in coastal_df.columns:
        coastal_df["rooms_per_household"] = coastal_df.apply(lambda r: safe_div(r.get("total_rooms"), r.get("households")), axis=1)
        explanatory_features.append("rooms_per_household")
    if "total_bedrooms" in coastal_df.columns and "total_rooms" in coastal_df.columns:
        coastal_df["bedrooms_per_room"] = coastal_df.apply(lambda r: safe_div(r.get("total_bedrooms"), r.get("total_rooms")), axis=1)
        explanatory_features.append("bedrooms_per_room")
    if "population" in coastal_df.columns and "households" in coastal_df.columns:
        coastal_df["population_per_household"] = coastal_df.apply(lambda r: safe_div(r.get("population"), r.get("households")), axis=1)
        explanatory_features.append("population_per_household")

    # Define "low coastal price" as price <= coastal 25th percentile.
    # If regression residuals are available, also require the property to be priced below what income would predict (residual < 0).
    if coastal_q25 is not None:
        if coastal_df["_price_residual"].notna().any():
            low_coastal_mask = (coastal_df[price_col] <= coastal_q25) & (coastal_df["_price_residual"] < 0)
        else:
            low_coastal_mask = (coastal_df[price_col] <= coastal_q25)
    else:
        low_coastal_mask = pd.Series([False] * len(coastal_df), index=coastal_df.index)

    low_coastal_df = coastal_df[low_coastal_mask].copy().reset_index(drop=True)

    # Prepare selected columns for output
    output_columns = [price_col, ocean_col]
    if income_col is not None:
        output_columns.append(income_col)
    for c in ["housing_median_age", "total_rooms", "total_bedrooms", "population", "households", "rooms_per_household", "bedrooms_per_room", "bedrooms_per_room", "bedrooms_per_room", "population_per_household", "_predicted_price_by_income", "_price_residual"]:
        if c in low_coastal_df.columns:
            output_columns.append(c)
    # Also include latitude/longitude if present
    for latc in ["latitude", "lat"]:
        if latc in low_coastal_df.columns:
            output_columns.append(latc)
            break
    for lonc in ["longitude", "lon", "lng"]:
        if lonc in low_coastal_df.columns:
            output_columns.append(lonc)
            break

    # Deduplicate columns preserving order
    seen = set()
    selected_output_columns = []
    for c in output_columns:
        if c in low_coastal_df.columns and c not in seen:
            selected_output_columns.append(c)
            seen.add(c)

    low_coastal_selected = low_coastal_df[selected_output_columns].copy()

    # Aggregate comparison statistics between low coastal and other coastal for explanatory features
    comparison = []
    features_for_comparison = []
    # choose numeric explanatory features we computed/found
    for f in explanatory_features:
        if f in coastal_df.columns and pd.api.types.is_numeric_dtype(coastal_df[f]):
            features_for_comparison.append(f)
    features_for_comparison = sorted(set(features_for_comparison))

    for f in features_for_comparison:
        low_vals = pd.to_numeric(low_coastal_df[f], errors="coerce").dropna()
        other_vals = pd.to_numeric(coastal_df.loc[~low_coastal_mask, f], errors="coerce").dropna()
        comparison.append({
            "feature": f,
            "low_coastal_mean": low_vals.mean() if len(low_vals) > 0 else pd.NA,
            "other_coastal_mean": other_vals.mean() if len(other_vals) > 0 else pd.NA,
            "difference (low - other)": (low_vals.mean() - other_vals.mean()) if (len(low_vals) > 0 and len(other_vals) > 0) else pd.NA,
            "low_coastal_count": len(low_vals),
            "other_coastal_count": len(other_vals)
        })
    comparison_df = pd.DataFrame(comparison).set_index("feature") if comparison else pd.DataFrame()

    # Summarize counts
    summary = {
        "coastal_rows_total": int(coastal_count),
        "coastal_mean_price": float(coastal_mean) if coastal_mean is not None else pd.NA,
        "coastal_price_25th_pct": float(coastal_q25) if coastal_q25 is not None else pd.NA,
        "coastal_price_std": float(coastal_std) if coastal_std is not None else pd.NA,
        "low_coastal_count": int(low_coastal_df.shape[0])
    }

    result = {
        "price_column_detected": price_col,
        "ocean_column_detected": ocean_col,
        "income_column_detected": income_col,
        "coastal_summary": summary,
        "low_coastal_samples": low_coastal_selected,         # DataFrame of coastal areas with relatively low prices
        "explanatory_comparison": comparison_df               # Comparison of means for explanatory features
    }
